import { accessibilityFixture, playwrightVersion } from './accessibility-fixture.ts';
import { loadTimedBoard } from './game-fixture.ts';

test('a complete keyboard journey exposes names, states and each result in Chromium accessibility trees', async ({
  page,
  context,
  browser,
}, artifacts) => {
  const expected = await accessibilityFixture();
  await loadTimedBoard(page);
  const session = await context.newCDPSession(page);
  await session.send('Accessibility.enable');
  const captures: { stage: string; tree: Awaited<ReturnType<typeof accessibilityTree>> }[] = [];
  async function capture(stage: string) {
    const tree = await accessibilityTree(session);
    captures.push({ stage, tree });
    return tree;
  }
  await page.getByRole('combobox', { name: expected.controls.size, exact: true }).focus();
  const controls = await capture('controls');
  expect(accessibilityNode(controls, 'combobox', expected.controls.size).properties.focused).toBe(
    true,
  );
  accessibilityNode(controls, 'button', expected.controls.newGame);
  await page.keyboard.press('Tab');
  expect(
    accessibilityNode(await capture('new-game-control'), 'button', expected.controls.newGame)
      .properties.focused,
  ).toBe(true);
  await page.keyboard.press('Tab');
  await page.keyboard.press('Tab');
  const closed = await capture('board-entry');
  for (const name of expected.closed) accessibilityNode(closed, 'button', name);
  expect(accessibilityNode(closed, 'button', expected.closed[0]).properties.focused).toBe(true);
  await page.getByRole('status').evaluate((element) => {
    const results: string[] = [];
    element.setAttribute('data-result-history', '[]');
    new MutationObserver(() => {
      results.push(element.textContent ?? '');
      element.setAttribute('data-result-history', JSON.stringify(results));
    }).observe(element, { childList: true, subtree: true, characterData: true });
  });
  for (const [turn, pair] of EXAMPLE_PAIRS.entries()) {
    await moveKeyboardTo(page, pair[0], expected.size);
    await page.keyboard.press('Enter');
    const revealed = await capture(`revealed-${turn + 1}`);
    expect(
      accessibilityNode(revealed, 'button', expected.revealed[pair[0]]).properties.focused,
    ).toBe(true);
    if (turn === 0) await page.clock.runFor(3000);
    await moveKeyboardTo(page, pair[1], expected.size);
    await page.keyboard.press('Space');
    const matched = await capture(`turn-${turn + 1}`);
    for (const index of pair)
      expect(
        accessibilityNode(matched, 'button', expected.matched[index]).properties.disabled,
      ).toBe(true);
    const result = accessibilityNode(matched, 'status');
    expect(result.properties.live).toBe('polite');
    expect(result.properties.atomic).toBe(true);
    expect(result.text).toBe(expected.turns[turn]);
  }
  const win = await capture('completed');
  expect(win.filter((node) => node.role === 'paragraph').map((node) => node.text)).toContain(
    expected.win,
  );
  const announcements: unknown = JSON.parse(
    (await page.getByRole('status').getAttribute('data-result-history')) ?? '[]',
  );
  expect(announcements).toEqual(expected.turns);
  await page.keyboard.press('Tab');
  expect(await page.locator('.card:focus').count()).toBe(0);
  const exit = await capture('board-exit');
  expect(
    accessibilityNode(exit, 'DisclosureTriangle', expected.controls.summary).properties.focused,
  ).toBe(true);
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Enter');
  const reset = await capture('new-game');
  expect(accessibilityNode(reset, 'button', expected.controls.newGame).properties.focused).toBe(
    true,
  );
  for (const name of expected.closed) accessibilityNode(reset, 'button', name);
  expect(accessibilityNode(reset, 'status').text).toBe(expected.newGame);
  await page.locator('summary').click();
  await page.getByRole('button', { name: 'Export snapshot', exact: true }).click();
  const snapshot = await page.getByLabel('Snapshot JSON', { exact: true }).inputValue();
  const loadEvents = [
    {
      stage: 'invalid-board',
      field: 'Board code',
      value: 'invalid',
      button: 'Load board',
      notice: 'Invalid board code.',
    },
    {
      stage: 'invalid-snapshot',
      field: 'Snapshot JSON',
      value: '{',
      button: 'Load snapshot',
      notice: 'Invalid snapshot.',
    },
    {
      stage: 'loaded-snapshot',
      field: 'Snapshot JSON',
      value: snapshot,
      button: 'Load snapshot',
      notice: 'Loaded snapshot. Select Resume to continue.',
    },
  ];
  for (const event of loadEvents) {
    await page.getByLabel(event.field, { exact: true }).fill(event.value);
    const button = page.getByRole('button', { name: event.button, exact: true });
    for (let repeat = 1; repeat <= 2; repeat += 1) {
      await button.click();
      await expect(button).toBeFocused();
      await expect(page.locator('.load-notice')).toHaveText(event.notice);
      const tree = await capture(`${event.stage}-${repeat}`);
      const status = accessibilityNode(tree, 'status');
      expect(tree.filter((node) => node.role === 'status')).toHaveLength(1);
      expect(status.properties.live).toBe('polite');
      expect(status.properties.atomic).toBe(true);
      expect(status.text).toBe(event.notice);
    }
  }
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toBeVisible();
  // A paused import blocks activation without marking its unmatched cards disabled.
  await expect(page.locator('.card[aria-disabled="true"]')).toHaveCount(0);
  expect(
    JSON.parse((await page.getByRole('status').getAttribute('data-result-history')) ?? '[]'),
  ).toEqual([
    ...expected.turns,
    expected.newGame,
    ...loadEvents.flatMap((event) => [event.notice, event.notice]),
  ]);
  const readme = await readFile(new URL('../README.md', import.meta.url), 'utf8');
  expect(readme.split(/\r?\n/)).toContain(expected.readmeRecord);
  const record =
    JSON.stringify(
      {
        schemaVersion: 1,
        status: 'tree-checked',
        chromium: browser.version(),
        playwright: await playwrightVersion(),
        screenReader: null,
        spokenReview: 'User acceptance. No spoken output was tested by the developer.',
        captures,
      },
      null,
      2,
    ) + '\n';
  expect(record).not.toMatch(
    /\b(?:file|https?):\/\/|[A-Za-z]:[\\/]|nodeId|frameId|backendDOMNodeId/,
  );
  await writeFile(artifacts.outputPath('accessibility-journey.json'), record);
  await session.detach();
}, {}, Scrollbars.hidden, TestTimeouts.long);

import assert from 'node:assert/strict';
import { test } from 'vitest';
import {
  activateCard,
  advanceGame,
  createGame,
  faceUpCards,
  isWon,
  MISMATCH_MS,
  ELAPSED_MAX_MS,
} from './game.ts';
import { SelectionKind } from './selection.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS, SPEC_VECTOR } from './game.fixture.ts';
import { formatElapsed } from './elapsed-time.ts';
import type { GameState } from './game.ts';

test('first reveal starts play without a move and ignores invalid activation', () => {
  const start = createGame(EXAMPLE_CODE);
  assert.equal(advanceGame(start, 300), start);
  const first = activateCard(start, 2);
  assert.equal(first.started, true, 'R07 first reveal starts time');
  assert.deepEqual(first.selection, { kind: SelectionKind.one, index: 2 });
  for (const index of [2, -1, 16, 0.5, NaN, Infinity])
    assert.equal(activateCard(first, index), first);
  assert.equal(first.moves, 0);
  assert.equal(activateCard(first, 6).moves, 1, 'R05 a different second card costs one move');
  assert.equal(start.started, false);
});

test('a matching pair stays up and costs exactly one move', () => {
  const result = activateCard(activateCard(createGame(EXAMPLE_CODE), 2), 6);
  assert.deepEqual(result.matched, [2, 6], 'R03 matching pair stays matched');
  assert.equal(result.selection.kind, SelectionKind.closed);
  assert.equal(result.moves, 1, 'R05 second distinct reveal adds one move');
  assert.equal(activateCard(result, 6), result);
});

test('a mismatch blocks all activation and closes together at the exact interval', () => {
  assert.equal(MISMATCH_MS, SPEC_VECTOR.mismatchMs);
  const mismatch = activateCard(activateCard(createGame(EXAMPLE_CODE), 0), 1);
  assert.equal(mismatch.moves, 1);
  for (const index of [0, 1, 2, 6])
    assert.equal(activateCard(mismatch, index), mismatch, 'R04 mismatch blocks activation');
  const pending = advanceGame(mismatch, SPEC_VECTOR.mismatchMs - 1);
  assert.deepEqual(pending.selection, {
    kind: SelectionKind.mismatch,
    first: 0,
    second: 1,
    remainingMs: 1,
  });
  const closed = advanceGame(pending, 1);
  assert.equal(closed.selection.kind, SelectionKind.closed, 'R04 mismatch closes at 800ms');
  assert.equal(closed.elapsedMs, SPEC_VECTOR.mismatchMs);
  assert.equal(activateCard(closed, 2).selection.kind, SelectionKind.one);
});

test('completion counts only matched pairs and stops the clock and later activation', () => {
  let state = createGame(EXAMPLE_CODE);
  for (const [first, second] of EXAMPLE_PAIRS) {
    state = activateCard(advanceGame(activateCard(state, first), 10), second);
  }
  assert.equal(isWon(state), true);
  assert.equal(state.matched.length / 2, EXAMPLE_PAIRS.length);
  assert.equal(state.moves, EXAMPLE_PAIRS.length);
  assert.equal(state.elapsedMs, 80);
  assert.equal(advanceGame(state, 100), state);
  assert.equal(activateCard(state, 0), state);
});

test('new states keep earlier games unchanged and reject invalid elapsed input', () => {
  const old = activateCard(activateCard(createGame(EXAMPLE_CODE), 0), 1);
  const current = createGame(EXAMPLE_CODE);
  advanceGame(old, MISMATCH_MS);
  assert.deepEqual(current, createGame(EXAMPLE_CODE));
  for (const delta of [-1, 0, Infinity, NaN]) assert.equal(advanceGame(old, delta), old);
  const capped = advanceGame({ ...old, elapsedMs: ELAPSED_MAX_MS - 1 }, Number.MAX_SAFE_INTEGER);
  assert.equal(capped.elapsedMs, ELAPSED_MAX_MS);
  assert.equal(capped.selection.kind, SelectionKind.closed);
  assert.equal(activateCard(capped, 2).selection.kind, SelectionKind.one);
  assert.equal(formatElapsed(capped.elapsedMs), '5999:59');
});

test('one active-time step advances elapsed and mismatch together', () => {
  const old = activateCard(activateCard(createGame(EXAMPLE_CODE), 0), 1);
  const before = advanceGame(old, 799);
  assert.equal(before.elapsedMs, 799);
  assert.deepEqual(before.selection, {
    kind: SelectionKind.mismatch,
    first: 0,
    second: 1,
    remainingMs: 1,
  });
  assert.equal(advanceGame(before, 1).selection.kind, SelectionKind.closed);
});

test('a card faces up while it is the one selection, either mismatch card or matched', () => {
  const faceUp = (state: GameState) => [...faceUpCards(state)].sort((left, right) => left - right);
  const start = createGame(EXAMPLE_CODE);
  assert.deepEqual(faceUp(start), []);
  const one = activateCard(start, 0);
  assert.deepEqual(faceUp(one), [0]);
  const mismatch = activateCard(one, 1);
  assert.deepEqual(faceUp(mismatch), [0, 1]);
  const matched = activateCard(activateCard(advanceGame(mismatch, MISMATCH_MS), 2), 6);
  assert.deepEqual(faceUp(matched), [2, 6]);
});
import { useEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import { tickSession } from './session.ts';
import type { RefObject } from 'react';
import type { Session } from './session.ts';

export function useSessionClock(
  session: Session,
  current: RefObject<Session>,
  commit: (next: Session) => void,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const won = isWon(session.game);

  function running(): boolean {
    return (
      visible.current &&
      !current.current.paused &&
      current.current.game.started &&
      !isWon(current.current.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tickSession(current.current, generation, step.milliseconds));
  }

  useEffect(() => {
    const generation = session.generation;
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!active || generation !== current.current.generation || !running()) return;
      const selection = current.current.game.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [session.generation, session.game.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}
